from django.contrib.auth.models import User
from django.db import models
from django.utils import timezone


class Recommendation(models.Model):
    """One piece of advice generated by the DSS for a specific prediction (day)."""

    APPLIANCE_SCHEDULE = 'APPLIANCE_SCHEDULE'
    BATTERY_CHARGE = 'BATTERY_CHARGE'
    BATTERY_RESERVE = 'BATTERY_RESERVE'
    BATTERY_DISCHARGE = 'BATTERY_DISCHARGE'
    GRID_EXPORT = 'GRID_EXPORT'
    GRID_IMPORT = 'GRID_IMPORT'
    ENERGY_CONSERVATION = 'ENERGY_CONSERVATION'
    GENERAL = 'GENERAL'
    TYPE_CHOICES = [
        (APPLIANCE_SCHEDULE, 'Appliance scheduling'),
        (BATTERY_CHARGE, 'Battery charging'),
        (BATTERY_RESERVE, 'Battery reserve'),
        (BATTERY_DISCHARGE, 'Battery discharge'),
        (GRID_EXPORT, 'Grid export'),
        (GRID_IMPORT, 'Grid import'),
        (ENERGY_CONSERVATION, 'Energy conservation'),
        (GENERAL, 'General'),
    ]

    LOW = 'LOW'
    MEDIUM = 'MEDIUM'
    HIGH = 'HIGH'
    CRITICAL = 'CRITICAL'
    PRIORITY_CHOICES = [(LOW, 'Low'), (MEDIUM, 'Medium'), (HIGH, 'High'), (CRITICAL, 'Critical')]

    user = models.ForeignKey(User, on_delete=models.CASCADE, related_name='recommendations')
    # CASCADE: when a stale prediction is deleted, the advice built on it goes too.
    prediction = models.ForeignKey('forecast.Prediction', on_delete=models.CASCADE,
                                   related_name='recommendations')
    appliance = models.ForeignKey('solar.Appliance', on_delete=models.SET_NULL,
                                  null=True, blank=True, related_name='recommendations')
    recommendation_type = models.CharField(max_length=25, choices=TYPE_CHOICES)
    title = models.CharField(max_length=150)
    message = models.TextField()
    priority = models.CharField(max_length=10, choices=PRIORITY_CHOICES, default=MEDIUM)
    estimated_energy_kwh = models.FloatField(null=True, blank=True)
    estimated_savings = models.FloatField(null=True, blank=True)
    created_at = models.DateTimeField(default=timezone.now)

    class Meta:
        ordering = ['-prediction__prediction_for_date', 'id']

    def __str__(self):
        return f"{self.get_recommendation_type_display()}: {self.title}"
